package main

import (
	"fmt"
	"net"
	"strings"
)

func getTargetForRedirect(target string, domain string) string {
	if target == "" {
		return "https://" + domain
	}

	// Parse the target URL
	parsedURL, err := net.ParseURL(target)
	if err != nil {
		return "https://" + domain
	}

	// Extract the host (domain part)
	targetHost := parsedURL.Host

	// Check if the target host is a subdomain of the provided domain
	if strings.HasSuffix(targetHost, "."+domain) {
		return target
	}

	return "https://" + domain
}

func main() {
	fmt.Println(getTargetForRedirect("https://music.example.com", "example.com"))       // "https://music.example.com"
	fmt.Println(getTargetForRedirect("https://example.com/service", "example.com"))     // "https://example.com/service"
	fmt.Println(getTargetForRedirect("https://blog.example.com/posts", "example.com"))  // "https://blog.example.com/posts"
	fmt.Println(getTargetForRedirect("https://another.com", "example.com"))             // "https://example.com"
}

